#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    string letters;
    cin >> letters;
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<long long> answers(n, 0);
    // counts of prefix masks of the parents of nodes on the current root path
    unordered_map<int, int> counts;
    counts.reserve(2 * n + 2);
    counts[0] = 1;
    auto get = [&](int key) { auto it = counts.find(key); return it == counts.end() ? 0 : it->second; };
    // stack entries: node, parent, mask, isExit
    vector<tuple<int, int, int, bool>> st = {{0, -1, 0, false}};
    while (!st.empty()) {
        auto [node, parent, mask, exit] = st.back();
        st.pop_back();
        if (exit) { counts[mask]--; continue; }
        mask ^= 1 << (letters[node] - 'a');
        long long c = get(mask);
        for (int b = 0; b < 26; b++) c += get(mask ^ (1 << b));
        answers[node] = c;
        counts[mask]++;
        st.push_back({node, parent, mask, true});
        for (int child : g[node]) if (child != parent) st.push_back({child, node, mask, false});
    }
    string out;
    for (int i = 0; i < m; i++) {
        int q;
        cin >> q;
        if (i) out += ' ';
        out += to_string(answers[q]);
    }
    out += '\n';
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static int nextInt() throws IOException {
        int c = read();
        while (c < '0' || c > '9') c = read();
        int r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return r;
    }

    static String nextWord() throws IOException {
        int c = read();
        while (c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        String letters = nextWord();
        int[] eu = new int[n - 1], ev = new int[n - 1], deg = new int[n + 1];
        for (int i = 0; i < n - 1; i++) { eu[i] = nextInt(); ev[i] = nextInt(); deg[eu[i] + 1]++; deg[ev[i] + 1]++; }
        // adjacency in CSR form
        for (int i = 0; i < n; i++) deg[i + 1] += deg[i];
        int[] adj = new int[2 * (n - 1)], fill = Arrays.copyOf(deg, n);
        for (int i = 0; i < n - 1; i++) { adj[fill[eu[i]]++] = ev[i]; adj[fill[ev[i]]++] = eu[i]; }
        long[] answers = new long[n];
        // counts of prefix masks of the parents of nodes on the current root path
        HashMap<Integer, Integer> counts = new HashMap<>(4 * n + 4);
        counts.put(0, 1);
        // stack of (node, parent, mask, isExit)
        int[] sNode = new int[2 * n + 2], sPar = new int[2 * n + 2], sMask = new int[2 * n + 2];
        boolean[] sExit = new boolean[2 * n + 2];
        int top = 0;
        sNode[top] = 0; sPar[top] = -1; sMask[top] = 0; sExit[top] = false; top++;
        while (top > 0) {
            top--;
            int node = sNode[top], parent = sPar[top], mask = sMask[top];
            if (sExit[top]) { counts.merge(mask, -1, Integer::sum); continue; }
            mask ^= 1 << (letters.charAt(node) - 'a');
            long c = counts.getOrDefault(mask, 0);
            for (int b = 0; b < 26; b++) c += counts.getOrDefault(mask ^ (1 << b), 0);
            answers[node] = c;
            counts.merge(mask, 1, Integer::sum);
            sNode[top] = node; sPar[top] = parent; sMask[top] = mask; sExit[top] = true; top++;
            for (int e = deg[node]; e < deg[node + 1]; e++) {
                int child = adj[e];
                if (child == parent) continue;
                sNode[top] = child; sPar[top] = node; sMask[top] = mask; sExit[top] = false; top++;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) { if (i > 0) sb.append(' '); sb.append(answers[nextInt()]); }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c < '0' || c > '9' {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	return n
}

func readWord() []byte {
	c, _ := rd.ReadByte()
	for c <= ' ' {
		c, _ = rd.ReadByte()
	}
	var b []byte
	for c > ' ' {
		b = append(b, c)
		c, _ = rd.ReadByte()
	}
	return b
}

type frame struct {
	node, parent, mask int
	exit               bool
}

func main() {
	n, m := readInt(), readInt()
	letters := readWord()
	g := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, b := readInt(), readInt()
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}
	answers := make([]int, n)
	// counts of prefix masks of the parents of nodes on the current root path
	counts := map[int]int{0: 1}
	st := []frame{{0, -1, 0, false}}
	for len(st) > 0 {
		f := st[len(st)-1]
		st = st[:len(st)-1]
		if f.exit {
			counts[f.mask]--
			continue
		}
		mask := f.mask ^ 1<<(letters[f.node]-'a')
		c := counts[mask]
		for b := 0; b < 26; b++ {
			c += counts[mask^1<<b]
		}
		answers[f.node] = c
		counts[mask]++
		st = append(st, frame{f.node, f.parent, mask, true})
		for _, child := range g[f.node] {
			if child != f.parent {
				st = append(st, frame{child, f.node, mask, false})
			}
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < m; i++ {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(answers[readInt()]))
	}
	w.WriteByte('\n')
}
